def kv_cache_bytes(layers, kv_heads, head_dim, seq_len, batch=1, dtype_bytes=2):
    # 2 = one key and one value per token, per layer
    return 2 * layers * kv_heads * head_dim * seq_len * batch * dtype_bytes


def max_concurrent_sequences(gpu_bytes, model_bytes, per_sequence_bytes, reserve_fraction=0.1):
    free_for_caches = gpu_bytes * (1 - reserve_fraction) - model_bytes
    if free_for_caches <= 0:
        return 0
    return int(free_for_caches // per_sequence_bytes)
